with a as (select distinct p.id as product_id from orders o join order_items oi on o.id = oi.order_id join products p on p.id = oi.product_id where o.created_at >= '2026-09-01 +07' and o.created_at < '2026-09-08 +07' and o.status <> 'cancelled'),b as (select distinct p.id as product_id from orders o join order_items oi on o.id = oi.order_id join products p on p.id = oi.product_id where o.created_at >= '2026-09-08 +07' and o.created_at < '2026-09-15 +07' and o.status <> 'cancelled') 
(select product_id, 'chỉ tuần 1' as nhom from(select product_id from a except select product_id from  b)) union (select product_id, 'chỉ tuần 2' as nhom from (select product_id from b except select product_id from a)) order by product_id asc;
